INSERT INTO parks (name, lat, lon, region) SELECT 'Aspen Snowmass Ski Resort', 39.2084, -106.949, 'Colorado, US' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Aspen Snowmass Ski Resort');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Breathtaker', 'Aspen Snowmass Ski Resort', 'Steel', 'Wiegand', 'Wiegand Alpine', NULL, 28.0, 2719.8, 0, NULL, 2017, '2017', 'year', NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Breathtaker' AND park = 'Aspen Snowmass Ski Resort');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Breathtaker' AND c.park = 'Aspen Snowmass Ski Resort' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
